import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Prevents canonical DTO, entity, event, snapshot and persistence boundary types from shadowing each other. */
public final class DuplicateBoundaryTypeCheck{
 private static final Pattern PACKAGE=Pattern.compile("\\bpackage\\s+([\\w.]+)\\s*;"),TYPE=Pattern.compile("(?m)^\\s*(?:public\\s+)?(?:final\\s+)?(?:class|record|interface)\\s+(\\w+)");
 private static final Pattern BOUNDARY=Pattern.compile(".*(?:Dto|DTO|Entity|Event|Snapshot|Payload|Command|Request|Response)$");
 public static void main(String[]args)throws Exception{Path root=Path.of(args[0]);Map<String,List<String>>owners=new TreeMap<>();try(var paths=Files.walk(root.resolve("server"))){for(Path path:paths.filter(Files::isRegularFile).filter(p->canonical(p.toString())).toList()){String body=Files.readString(path).replaceAll("(?s)/\\*.*?\\*/"," ").replaceAll("(?m)//.*$"," ");Matcher pkg=PACKAGE.matcher(body),type=TYPE.matcher(body);if(!pkg.find()||!type.find()||!pkg.group(1).startsWith("com.aoo.")||!BOUNDARY.matcher(type.group(1)).matches())continue;owners.computeIfAbsent(type.group(1),ignored->new ArrayList<>()).add(pkg.group(1)+'.'+type.group(1)+" @ "+root.relativize(path));}}List<String>failures=owners.entrySet().stream().filter(entry->entry.getValue().size()>1).map(entry->entry.getKey()+": "+entry.getValue()).toList();Path out=root.resolve("work/audit/dead05-boundary-types.txt");Files.createDirectories(out.getParent());Files.writeString(out,failures.isEmpty()?"DEAD05 passed: canonical DTO/entity/event/snapshot boundary names have unique ownership; legacy packages remain outside the Aoo import boundary.\n":String.join("\n",failures)+"\n");if(!failures.isEmpty())throw new IllegalStateException("duplicate boundary types: "+failures.size());System.out.println("Duplicate boundary type check passed: "+owners.size()+" types.");}
 private static boolean canonical(String raw){String path=raw.replace('\\','/').toLowerCase(Locale.ROOT);return path.endsWith(".java")&&path.contains("/src/main/java/")&&!path.contains("/target/")&&!path.contains("/build/")&&!path.contains("/legacy/");}
}
